'use client';

import React, { useState, useRef, useEffect } from 'react';
import { Bold, Italic, Underline, Link, List, Sparkles, Download, Printer, Bookmark, Check, X, RotateCcw } from 'lucide-react';
import type { DraftingStep, Variable } from '@/app/drafting/page';

interface DraftingEditorProps {
  step: DraftingStep;
  streamedContent: string;
  isStreaming: boolean;
  variables: Variable[];
  saveStatus: 'idle' | 'saving' | 'saved';
  onFillVariable: (id: string, value: string) => void;
}

interface FloatingToolbar {
  visible: boolean;
  x: number;
  y: number;
}

interface EditingVariable {
  id: string;
  label: string;
  tempValue: string;
}

export function DraftingEditor({ step, streamedContent, isStreaming, variables, saveStatus, onFillVariable }: DraftingEditorProps) {
  const [toolbar, setToolbar] = useState<FloatingToolbar>({ visible: false, x: 0, y: 0 });
  const [showAiMenu, setShowAiMenu] = useState(false);
  const [editingVar, setEditingVar] = useState<EditingVariable | null>(null);
  const [showExportModal, setShowExportModal] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);
  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll during streaming
  useEffect(() => {
    if (isStreaming) {
      bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [streamedContent, isStreaming]);

  // Floating toolbar on text selection
  useEffect(() => {
    const handleSelectionChange = () => {
      const sel = window.getSelection();
      if (sel && sel.toString().trim().length > 0 && contentRef.current?.contains(sel.anchorNode)) {
        const range = sel.getRangeAt(0);
        const rect = range.getBoundingClientRect();
        const containerRect = contentRef.current.getBoundingClientRect();
        setToolbar({ visible: true, x: rect.left + rect.width / 2 - containerRect.left, y: rect.top - containerRect.top - 52 });
      } else {
        if (!showAiMenu) setToolbar(t => ({ ...t, visible: false }));
      }
    };
    document.addEventListener('selectionchange', handleSelectionChange);
    return () => document.removeEventListener('selectionchange', handleSelectionChange);
  }, [showAiMenu]);

  const unfilledCount = variables.filter(v => !v.filled).length;

  // Render content with variable highlighting
  const renderContent = () => {
    if (!streamedContent) return null;
    const parts: React.ReactNode[] = [];
    let remaining = streamedContent;
    let keyIdx = 0;

    variables.forEach(v => {
      const marker = `[${v.label}]`;
      const idx = remaining.indexOf(marker);
      if (idx !== -1 && !v.filled) {
        parts.push(<span key={`text-${keyIdx++}`}>{remaining.slice(0, idx)}</span>);
        parts.push(
          <button
            key={`var-${v.id}`}
            onClick={() => setEditingVar({ id: v.id, label: v.label, tempValue: '' })}
            className="bg-orange-100 text-orange-800 rounded px-1 mx-0.5 hover:bg-orange-200 transition-colors cursor-pointer border-b border-orange-300 border-dashed"
            title="انقر لتعبئة هذه البيانات"
          >
            {marker}
          </button>
        );
        remaining = remaining.slice(idx + marker.length);
      }
    });

    parts.push(<span key={`text-final`}>{remaining}</span>);
    return parts;
  };

  // Pre-generation empty state
  if (step === 'select' || step === 'wizard' || step === 'tone') {
    return (
      <div className="flex flex-col h-full bg-slate-50 items-center justify-center">
        <div className="w-full max-w-2xl bg-white shadow-sm rounded-md border border-dashed border-slate-200 mx-8 my-8 flex items-center justify-center" style={{ minHeight: '70vh' }}>
          <div className="text-center p-12">
            <div className="w-16 h-16 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-center mx-auto mb-4">
              <Sparkles className="w-8 h-8 text-slate-200" />
            </div>
            <p className="text-slate-200 text-2xl font-light italic">ستظهر مسودتك هنا...</p>
            <p className="text-slate-300 text-sm mt-2">أجب على أسئلة المساعد في الجانب الأيمن لتوليد المستند</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      {/* Top Bar */}
      <div className="sticky top-0 z-20 bg-white/90 backdrop-blur-sm border-b border-gray-100 px-8 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          {/* Save Status */}
          <span className={`flex items-center gap-1.5 text-xs transition-all duration-300 ${
            saveStatus === 'idle' ? 'text-transparent' :
            saveStatus === 'saving' ? 'text-slate-400' : 'text-green-500'
          }`}>
            {saveStatus === 'saving' && <div className="w-3 h-3 rounded-full border border-slate-400 border-t-transparent animate-spin" />}
            {saveStatus === 'saved' && <Check className="w-3 h-3" />}
            {saveStatus === 'saving' ? 'جاري الحفظ...' : 'تم الحفظ'}
          </span>

          {/* Variables indicator */}
          {unfilledCount > 0 && (
            <span className="flex items-center gap-1.5 text-xs bg-orange-50 text-orange-600 border border-orange-100 px-2 py-1 rounded-full">
              <div className="w-2 h-2 rounded-full bg-orange-400" />
              {unfilledCount} متغيرات ناقصة
            </span>
          )}
          {unfilledCount === 0 && variables.length > 0 && (
            <span className="flex items-center gap-1.5 text-xs bg-green-50 text-green-600 border border-green-100 px-2 py-1 rounded-full">
              <Check className="w-3 h-3" />
              المستند مكتمل
            </span>
          )}
        </div>

        <div className="flex items-center gap-2">
          <button className="p-2 text-slate-500 hover:text-navy-900 hover:bg-slate-100 rounded-md transition-colors">
            <RotateCcw className="w-4 h-4" />
          </button>
          <button className="p-2 text-slate-500 hover:text-navy-900 hover:bg-slate-100 rounded-md transition-colors">
            <Printer className="w-4 h-4" />
          </button>
          <button className="p-2 text-slate-500 hover:text-navy-900 hover:bg-slate-100 rounded-md transition-colors">
            <Bookmark className="w-4 h-4" />
          </button>
          <div className="w-px h-5 bg-slate-200 mx-1" />
          <button
            onClick={() => setShowExportModal(true)}
            className="flex items-center gap-2 bg-navy-900 text-white text-sm px-4 py-2 rounded-lg hover:bg-slate-800 transition-colors"
          >
            <Download className="w-4 h-4" />
            تصدير المستند
          </button>
        </div>
      </div>

      {/* Document Paper */}
      <div className="flex-1 overflow-y-auto py-8 px-8" ref={contentRef}>
        <div className="max-w-2xl mx-auto bg-white shadow-sm rounded-sm" style={{ minHeight: '85vh', padding: '4rem 5rem' }}>

          {/* Floating Toolbar */}
          {toolbar.visible && (
            <div
              className="absolute z-30 bg-gray-900 text-white rounded-lg shadow-xl flex items-center gap-1 px-2 py-1.5 transform -translate-x-1/2"
              style={{ top: toolbar.y, left: toolbar.x }}
              onMouseDown={e => e.preventDefault()}
            >
              <button className="p-1.5 hover:bg-gray-700 rounded transition-colors"><Bold className="w-3.5 h-3.5" /></button>
              <button className="p-1.5 hover:bg-gray-700 rounded transition-colors"><Italic className="w-3.5 h-3.5" /></button>
              <button className="p-1.5 hover:bg-gray-700 rounded transition-colors"><Underline className="w-3.5 h-3.5" /></button>
              <div className="w-px h-4 bg-gray-700 mx-1" />
              <button className="p-1.5 hover:bg-gray-700 rounded transition-colors"><Link className="w-3.5 h-3.5" /></button>
              <button className="p-1.5 hover:bg-gray-700 rounded transition-colors"><List className="w-3.5 h-3.5" /></button>
              <div className="w-px h-4 bg-gray-700 mx-1" />
              <div className="relative">
                <button
                  onClick={() => setShowAiMenu(p => !p)}
                  className="p-1.5 hover:bg-blue-600 rounded transition-colors flex items-center gap-1 text-blue-400 hover:text-white"
                >
                  <Sparkles className="w-3.5 h-3.5" />
                  <span className="text-[10px]">AI</span>
                </button>
                {showAiMenu && (
                  <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 bg-white border border-gray-100 rounded-xl shadow-xl py-2 w-56 text-navy-900 z-40">
                    {[
                      { icon: '🔄', label: 'أعد الصياغة بلغة قانونية' },
                      { icon: '✂️', label: 'اختصر هذه الفقرة' },
                      { icon: '⚖️', label: 'ابحث عن سند قانوني' },
                      { icon: '💬', label: 'حوّل للأسلوب الودي' },
                      { icon: '📊', label: 'اشرح بلغة بسيطة' },
                    ].map(action => (
                      <button key={action.label} onClick={() => setShowAiMenu(false)}
                        className="w-full text-right flex items-center gap-3 px-4 py-2.5 hover:bg-slate-50 transition-colors text-sm">
                        <span>{action.icon}</span>
                        <span>{action.label}</span>
                      </button>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Document Content */}
          <div className="leading-loose text-slate-800 font-light whitespace-pre-wrap text-right" dir="rtl">
            {renderContent()}
            {isStreaming && (
              <span className="inline-block w-0.5 h-5 bg-blue-600 animate-pulse ml-0.5 align-middle" />
            )}
          </div>
          <div ref={bottomRef} />
        </div>
      </div>

      {/* Variable Fill Modal */}
      {editingVar && (
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm z-50 flex items-center justify-center" onClick={() => setEditingVar(null)}>
          <div className="bg-white rounded-2xl shadow-2xl p-6 w-96 animate-slide-up" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-semibold text-navy-900">تعبئة البيانات الناقصة</h3>
              <button onClick={() => setEditingVar(null)} className="text-slate-400 hover:text-slate-600">
                <X className="w-5 h-5" />
              </button>
            </div>
            <p className="text-sm text-slate-500 mb-3">{editingVar.label}</p>
            <input
              autoFocus
              type="text"
              value={editingVar.tempValue}
              onChange={e => setEditingVar(prev => prev ? { ...prev, tempValue: e.target.value } : null)}
              onKeyDown={e => {
                if (e.key === 'Enter' && editingVar.tempValue) {
                  onFillVariable(editingVar.id, editingVar.tempValue);
                  setEditingVar(null);
                }
              }}
              placeholder="أدخل القيمة هنا..."
              className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all"
            />
            <div className="flex gap-2 mt-4">
              <button onClick={() => setEditingVar(null)} className="flex-1 py-2.5 border border-gray-200 text-sm rounded-xl text-slate-500 hover:bg-slate-50 transition-colors">
                إلغاء
              </button>
              <button
                onClick={() => { if (editingVar.tempValue) { onFillVariable(editingVar.id, editingVar.tempValue); setEditingVar(null); } }}
                disabled={!editingVar.tempValue}
                className="flex-1 py-2.5 bg-blue-600 disabled:bg-blue-300 text-white text-sm rounded-xl hover:bg-blue-700 transition-colors font-medium"
              >
                تأكيد وإدراج
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Export Modal */}
      {showExportModal && (
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm z-50 flex items-center justify-center" onClick={() => setShowExportModal(false)}>
          <div className="bg-white rounded-2xl shadow-2xl p-6 w-[420px] animate-slide-up" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-5">
              <h3 className="font-bold text-navy-900 text-lg">تصدير المستند</h3>
              <button onClick={() => setShowExportModal(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="space-y-3 mb-5">
              <p className="text-xs text-slate-500 font-medium uppercase tracking-wide">صيغة الملف</p>
              {[
                { id: 'pdf-draft', label: 'PDF مسودة', desc: 'مع ختم "مسودة - غير رسمي"' },
                { id: 'pdf-final', label: 'PDF نهائي', desc: 'جاهز للتوقيع والتقديم', selected: true },
                { id: 'docx', label: 'Word (.docx)', desc: 'قابل للتعديل في Microsoft Word' },
              ].map(f => (
                <label key={f.id} className={`flex items-start gap-3 p-3 rounded-xl border cursor-pointer transition-colors ${f.selected ? 'border-blue-500 bg-blue-50' : 'border-gray-100 hover:border-gray-200'}`}>
                  <div className={`w-4 h-4 rounded-full border-2 mt-0.5 flex-shrink-0 ${f.selected ? 'border-blue-500 bg-blue-500' : 'border-gray-300'}`} />
                  <div>
                    <p className="font-medium text-sm text-navy-900">{f.label}</p>
                    <p className="text-xs text-slate-500">{f.desc}</p>
                  </div>
                </label>
              ))}
            </div>

            <div className="space-y-2 mb-6 border-t pt-4">
              <p className="text-xs text-slate-500 font-medium uppercase tracking-wide">خيارات إضافية</p>
              {['تضمين أرقام المواد القانونية', 'إضافة تذييل الصفحة مع اسم المحامي', 'إضافة صفحة الخاتمة القانونية'].map((opt, i) => (
                <label key={opt} className="flex items-center gap-3 py-1 cursor-pointer">
                  <div className={`w-4 h-4 rounded border-2 flex items-center justify-center ${i < 2 ? 'border-blue-500 bg-blue-500' : 'border-gray-300'}`}>
                    {i < 2 && <Check className="w-2.5 h-2.5 text-white" />}
                  </div>
                  <span className="text-sm text-navy-900">{opt}</span>
                </label>
              ))}
            </div>

            <div className="flex gap-2">
              <button onClick={() => setShowExportModal(false)} className="flex-1 py-3 border border-gray-200 text-sm rounded-xl text-slate-500 hover:bg-slate-50 transition-colors">
                إلغاء
              </button>
              <button onClick={() => setShowExportModal(false)}
                className="flex-1 py-3 bg-navy-900 text-white text-sm rounded-xl hover:bg-slate-800 transition-colors font-semibold flex items-center justify-center gap-2">
                <Download className="w-4 h-4" />
                تصدير الآن
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
